import{_ as a,o as t,c as s,a1 as i}from"./chunks/framework.C5u0ZYB0.js";const u=JSON.parse('{"title":"Installing","description":"","frontmatter":{},"headers":[],"relativePath":"docs/installing.md","filePath":"docs/installing.md","lastUpdated":1790670035000}'),n={name:"docs/installing.md"};function o(r,e,l,h,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h1><p>Aquilifer is on the Chrome Web Store. Installing from there is the recommended path for everyone who isn&#39;t working on Aquilifer itself; building from source is documented further down for contributors.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>A Chromium-based browser (Chrome, Edge, Brave, etc.). Aquilifer currently targets Chrome&#39;s Manifest V3 only. Firefox and other browsers aren&#39;t supported yet.</p><p>Building from source additionally needs <a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js</a> (a recent LTS version) and npm.</p><h2 id="install-from-the-chrome-web-store" tabindex="-1">Install from the Chrome Web Store <a class="header-anchor" href="#install-from-the-chrome-web-store" aria-label="Permalink to &quot;Install from the Chrome Web Store&quot;">​</a></h2><p><strong><a href="https://chromewebstore.google.com/detail/aquilifer/aflcbgcgkaenbkecookfmndjgmgdancg" target="_blank" rel="noreferrer">Add Aquilifer to Chrome</a></strong></p><p>Click <strong>Add to Chrome</strong>, then confirm the permission dialog (see the note below on what it&#39;s asking for). Aquilifer&#39;s icon should appear in your browser toolbar once it&#39;s installed.</p><p>Next: <a href="/projects/aquilifer/docs/providers">connect a provider</a> and <a href="/projects/aquilifer/docs/connecting">try connecting a site</a>.</p><h3 id="about-the-read-and-change-all-your-data-on-all-websites-warning" tabindex="-1">About the &quot;read and change all your data on all websites&quot; warning <a class="header-anchor" href="#about-the-read-and-change-all-your-data-on-all-websites-warning" aria-label="Permalink to &quot;About the &quot;read and change all your data on all websites&quot; warning&quot;">​</a></h3><p>Chrome shows this in the install dialog, on the Web Store listing, and on the extension&#39;s <code>chrome://extensions</code> details page. It&#39;s expected, and it&#39;s what lets any website detect Aquilifer and offer to connect without you doing anything extension-specific first, the same MetaMask-style pattern <code>window.ethereum</code> uses. MetaMask itself requests the same broad access for the same reason. Aquilifer never acts on a page without your explicit, visible approval (see <a href="/projects/aquilifer/docs/connecting">Connecting a site</a>); the broad access is about where the connection <em>offer</em> can appear, not what it&#39;s allowed to do without you.</p><h2 id="staying-up-to-date" tabindex="-1">Staying up to date <a class="header-anchor" href="#staying-up-to-date" aria-label="Permalink to &quot;Staying up to date&quot;">​</a></h2><p>Chrome updates Web Store extensions automatically in the background, so a store install needs nothing from you. Each release is also tagged on <a href="https://github.com/On0n0k1/aquilifer/releases" target="_blank" rel="noreferrer">GitHub</a> if you want to read what changed.</p><p>A source install doesn&#39;t auto-update — see below.</p><h2 id="installing-from-source" tabindex="-1">Installing from source <a class="header-anchor" href="#installing-from-source" aria-label="Permalink to &quot;Installing from source&quot;">​</a></h2><p>You only need this if you&#39;re developing Aquilifer or want to run an unreleased change. A source install and a store install are the same extension, but Chrome treats them as two separate items, so don&#39;t run both at once.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/On0n0k1/aquilifer.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aquilifer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Then load it:</p><ol><li>Open <code>chrome://extensions</code>.</li><li>Turn on <strong>Developer mode</strong> (top right).</li><li>Click <strong>Load unpacked</strong>.</li><li>Select the <code>.output/chrome-mv3</code> folder that <code>npm run build</code> created.</li></ol><p>To update a source install, pull and rebuild, then reload the extension from <code>chrome://extensions</code> (the reload icon on Aquilifer&#39;s card):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>See <a href="https://github.com/On0n0k1/aquilifer/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> for the full development setup.</p>`,22)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
